<div class="d-flex justify-content-between align-items-center mb-4"><div><h4 class="fw-bold">Kartu Hasil Studi</h4><div class="muted">Rekap nilai berdasarkan tahun ajaran dan semester.</div></div><div class="text-end"><div class="muted small">IPK Kumulatif</div><div class="display-6 fw-bold text-primary"><?= esc($ipk) ?></div></div></div><?php foreach($cards as $c): ?><div class="panel mb-4"><div class="d-flex justify-content-between"><h5 class="fw-bold"><?= esc($c['period']) ?></h5><span class="badge text-bg-primary">IP <?= esc($c['ip']) ?></span></div><div class="table-responsive"><table class="table"><thead><tr><th>Kode</th><th>Mata Kuliah</th><th>SKS</th><th>Nilai</th></tr></thead><tbody><?php foreach($c['rows'] as $r): ?><tr><td><?= esc($r['kode']) ?></td><td><?= esc($r['nama']) ?></td><td><?= esc($r['sks']) ?></td><td><?= esc($r['nilai']??'Belum dinilai') ?></td></tr><?php endforeach ?></tbody></table></div></div><?php endforeach ?><?php if(!$cards): ?><div class="panel muted">Belum ada riwayat studi.</div><?php endif ?>